kernels.cuda:
// Inclusive prefix sum along each row of a [rows, cols] matrix:
//   y[r, c] = x[r, 0] + ... + x[r, c]
// One block per row. The row is processed in BLOCK-sized chunks; each chunk
// is scanned in shared memory (Hillis-Steele) and offset by the running
// total of the previous chunks. Accumulates in float.
#include <cuda_fp16.h>
#include <cuda_bf16.h>

#define BLOCK 256

template <typename T>
__global__ void cumsum(const T* __restrict__ x, T* __restrict__ y, int rows, int cols) {
    __shared__ float buf[BLOCK];
    __shared__ float carry;
    const T* xr = x + (size_t)blockIdx.x * cols;
    T* yr = y + (size_t)blockIdx.x * cols;
    int tid = threadIdx.x;
    if (tid == 0) carry = 0.0f;
    __syncthreads();

    for (int start = 0; start < cols; start += BLOCK) {
        int c = start + tid;
        buf[tid] = c < cols ? (float)xr[c] : 0.0f;
        __syncthreads();
        // Hillis-Steele inclusive scan of buf.
        for (int off = 1; off < BLOCK; off <<= 1) {
            float add = tid >= off ? buf[tid - off] : 0.0f;
            __syncthreads();
            buf[tid] += add;
            __syncthreads();
        }
        if (c < cols) yr[c] = (T)(carry + buf[tid]);
        __syncthreads();
        if (tid == 0) carry += buf[BLOCK - 1];
        __syncthreads();
    }
}

kernels.wgsl:
var<workgroup> buf: array<f32, 256>;
var<workgroup> carry: f32;

@compute @workgroup_size(256)
fn main(@builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_index) tid: u32) {
    let cols = u32(params.cols);
    let base = wid.x * cols;
    if (tid == 0u) { carry = 0.0; }
    workgroupBarrier();
    for (var start = 0u; start < cols; start += 256u) {
        let c = start + tid;
        buf[tid] = select(0.0, f32(x[base + min(c, cols - 1u)]), c < cols);
        workgroupBarrier();
        for (var off = 1u; off < 256u; off <<= 1u) {
            var add = 0.0;
            if (tid >= off) { add = buf[tid - off]; }
            workgroupBarrier();
            buf[tid] += add;
            workgroupBarrier();
        }
        if (c < cols) { y[base + c] = T(carry + buf[tid]); }
        workgroupBarrier();
        if (tid == 0u) { carry += buf[255]; }
        workgroupBarrier();
    }
}

