kernels.cuda:
// LayerNorm over the last dim of a [rows, cols] matrix:
//   y = (x - mean) / sqrt(var + eps) * gamma + beta
// One block per row. Two-pass (mean, then variance of x - mean) in float.
#include <cuda_fp16.h>
#include <cuda_bf16.h>

#define BLOCK 256

__device__ float block_sum(float v, float* smem) {
    int tid = threadIdx.x;
    smem[tid] = v;
    __syncthreads();
    for (int s = BLOCK / 2; s > 0; s >>= 1) {
        if (tid < s) smem[tid] += smem[tid + s];
        __syncthreads();
    }
    float r = smem[0];
    __syncthreads();  // smem is reused by the next call
    return r;
}

template <typename T>
__global__ void layernorm(const T* __restrict__ x, const T* __restrict__ gamma,
                          const T* __restrict__ beta, T* __restrict__ y,
                          int rows, int cols, float eps) {
    __shared__ float smem[BLOCK];
    const T* xr = x + (size_t)blockIdx.x * cols;
    T* yr = y + (size_t)blockIdx.x * cols;

    float s = 0.0f;
    for (int c = threadIdx.x; c < cols; c += BLOCK) s += (float)xr[c];
    float mean = block_sum(s, smem) / cols;

    float sq = 0.0f;
    for (int c = threadIdx.x; c < cols; c += BLOCK) {
        float d = (float)xr[c] - mean;
        sq += d * d;
    }
    float rstd = rsqrtf(block_sum(sq, smem) / cols + eps);

    for (int c = threadIdx.x; c < cols; c += BLOCK) {
        float v = ((float)xr[c] - mean) * rstd;
        yr[c] = (T)(v * (float)gamma[c] + (float)beta[c]);
    }
}

kernels.wgsl:
var<workgroup> red: array<f32, 256>;

fn block_sum(v: f32, tid: u32) -> f32 {
    red[tid] = v;
    workgroupBarrier();
    for (var s = 128u; s > 0u; s >>= 1u) {
        if (tid < s) { red[tid] += red[tid + s]; }
        workgroupBarrier();
    }
    let r = red[0];
    workgroupBarrier();
    return r;
}

@compute @workgroup_size(256)
fn main(@builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_index) tid: u32) {
    let cols = u32(params.cols);
    let base = wid.x * cols;
    var s = 0.0;
    for (var c = tid; c < cols; c += 256u) { s += f32(x[base + c]); }
    let mean = block_sum(s, tid) / f32(cols);
    var q = 0.0;
    for (var c = tid; c < cols; c += 256u) {
        let d = f32(x[base + c]) - mean;
        q += d * d;
    }
    let rstd = 1.0 / sqrt(block_sum(q, tid) / f32(cols) + params.eps);
    for (var c = tid; c < cols; c += 256u) {
        y[base + c] = T((f32(x[base + c]) - mean) * rstd * f32(gamma[c]) + f32(beta[c]));
    }
}

