kernels.cuda:
// Naive matrix multiply: C[M, N] = A[M, K] @ B[K, N], all row-major.
// One thread per output element; accumulates in float.
#include <cuda_fp16.h>
#include <cuda_bf16.h>

template <typename T>
__global__ void matmul_naive(const T* __restrict__ A, const T* __restrict__ B, T* __restrict__ C,
                             int M, int N, int K) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < M && col < N) {
        float acc = 0.0f;
        for (int k = 0; k < K; ++k) acc += (float)A[(size_t)row * K + k] * (float)B[(size_t)k * N + col];
        C[(size_t)row * N + col] = (T)acc;
    }
}

kernels.wgsl:
@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let M = u32(params.M);
    let N = u32(params.N);
    let K = u32(params.K);
    let col = gid.x;
    let row = gid.y;
    if (row < M && col < N) {
        var acc = 0.0;
        for (var k = 0u; k < K; k++) { acc += f32(A[row * K + k]) * f32(B[k * N + col]); }
        C[row * N + col] = T(acc);
    }
}

