@group(0) @binding(3) var<uniform> params: Params;

kernels.cuda:
// Full sum reduction: *out += sum(x[0..n)). Accumulates in float.
// Each block reduces a grid-stride slice in shared memory, then thread 0
// adds the block's partial into *out with atomicAdd. *out must start at 0.
#include <cuda_fp16.h>
#include <cuda_bf16.h>

#define BLOCK 256

template <typename T>
__global__ void reduce_sum(const T* __restrict__ x, float* __restrict__ out, int n) {
    __shared__ float smem[BLOCK];
    int tid = threadIdx.x;
    float acc = 0.0f;
    for (int i = blockIdx.x * BLOCK + tid; i < n; i += gridDim.x * BLOCK) acc += (float)x[i];
    smem[tid] = acc;
    __syncthreads();
    for (int s = BLOCK / 2; s > 0; s >>= 1) {
        if (tid < s) smem[tid] += smem[tid + s];
        __syncthreads();
    }
    if (tid == 0) atomicAdd(out, smem[0]);
}

kernels.wgsl:
var<workgroup> red: array<f32, 256>;

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3<u32>,
        @builtin(local_invocation_index) tid: u32,
        @builtin(num_workgroups) nwg: vec3<u32>) {
    let n = u32(params.n);
    var acc = 0.0;
    for (var i = gid.x; i < n; i += nwg.x * 256u) { acc += f32(x[i]); }
    red[tid] = acc;
    workgroupBarrier();
    for (var s = 128u; s > 0u; s >>= 1u) {
        if (tid < s) { red[tid] += red[tid + s]; }
        workgroupBarrier();
    }
    if (tid == 0u) {
        let partial = red[0];
        var old = atomicLoad(&out[0]);
        loop {
            let r = atomicCompareExchangeWeak(&out[0], old, bitcast<u32>(bitcast<f32>(old) + partial));
            if (r.exchanged) { break; }
            old = r.old_value;
        }
    }
}

