// Row-wise softmax over a [rows, cols] row-major matrix.
// One block per row; each thread strides over the columns. Accumulates in
// float, uses the max-subtraction trick for numerical stability.
#include <cuda_fp16.h>
#include <cuda_bf16.h>

#define BLOCK 256

template <typename T>
__global__ void softmax(const T* __restrict__ x, T* __restrict__ y, int rows, int cols) {
    __shared__ float red[BLOCK];
    int row = blockIdx.x;
    int tid = threadIdx.x;
    const T* xr = x + (size_t)row * cols;
    T* yr = y + (size_t)row * cols;

    // 1) row max
    float m = -INFINITY;
    for (int c = tid; c < cols; c += BLOCK) m = fmaxf(m, (float)xr[c]);
    red[tid] = m;
    __syncthreads();
    for (int s = BLOCK / 2; s > 0; s >>= 1) {
        if (tid < s) red[tid] = fmaxf(red[tid], red[tid + s]);
        __syncthreads();
    }
    m = red[0];
    __syncthreads();

    // 2) sum of exp(x - max)
    float sum = 0.0f;
    for (int c = tid; c < cols; c += BLOCK) sum += expf((float)xr[c] - m);
    red[tid] = sum;
    __syncthreads();
    for (int s = BLOCK / 2; s > 0; s >>= 1) {
        if (tid < s) red[tid] += red[tid + s];
        __syncthreads();
    }
    float inv = 1.0f / red[0];

    // 3) normalise
    for (int c = tid; c < cols; c += BLOCK) yr[c] = (T)(expf((float)xr[c] - m) * inv);
}

kernels.wgsl:
var<workgroup> red: array<f32, 256>;

fn block_max(v: f32, tid: u32) -> f32 {
    red[tid] = v;
    workgroupBarrier();
    for (var s = 128u; s > 0u; s >>= 1u) {
        if (tid < s) { red[tid] = max(red[tid], red[tid + s]); }
        workgroupBarrier();
    }
    let r = red[0];
    workgroupBarrier();
    return r;
}

fn block_sum(v: f32, tid: u32) -> f32 {
    red[tid] = v;
    workgroupBarrier();
    for (var s = 128u; s > 0u; s >>= 1u) {
        if (tid < s) { red[tid] += red[tid + s]; }
        workgroupBarrier();
    }
    let r = red[0];
    workgroupBarrier();
    return r;
}

@compute @workgroup_size(256)
fn main(@builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_index) tid: u32) {
    let cols = u32(params.cols);
    let base = wid.x * cols;
    var m = -3.4028234e38;                  // WGSL has no inf literal; this rounds to -FLT_MAX, the identity
    for (var c = tid; c < cols; c += 256u) { m = max(m, f32(x[base + c])); }
    m = block_max(m, tid);
    var s = 0.0;
    for (var c = tid; c < cols; c += 256u) { s += exp(f32(x[base + c]) - m); }
    let inv = 1.0 / block_sum(s, tid);
    for (var c = tid; c < cols; c += 256u) { y[base + c] = T(exp(f32(x[base + c]) - m) * inv); }
}

alias T = f32;
@group(0) @binding(0) var<storage, read> x: array<T>;
